mapper.update:
update ujcms_config
set port_ = #{port}
where id_ = 1

update ujcms_config
set install_state_ = 'coreReady', install_token_hash_ = #{tokenHash}
where id_ = 1 and (install_state_ is null or install_state_ != 'installed')

update ujcms_config
set marketplace_settings_ = #{marketplaceSettings,jdbcType=VARCHAR,typeHandler=com.ujcms.cms.core.security.Sm4StringTypeHandler}
where id_ = 1
